import{_ as o,o as a,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"多仓库与 Monorepo","description":"","frontmatter":{"title":"多仓库与 Monorepo","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/architecture/monorepo.md","filePath":"frontend/decisions/architecture/monorepo.md","lastUpdated":1785589115000}'),d={name:"frontend/decisions/architecture/monorepo.md"};function n(i,t,l,h,p,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="多仓库与-monorepo" tabindex="-1">多仓库与 Monorepo <a class="header-anchor" href="#多仓库与-monorepo" aria-label="Permalink to &quot;多仓库与 Monorepo&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>仓库策略决定代码如何协作、版本如何传播和自动化如何执行。Monorepo 能让跨包修改原子提交并统一治理，但不会自动带来模块边界；多仓库提供更强的权限和生命周期隔离，也会增加跨仓协调和版本传播成本。</p><p>工程实现参见<a href="/frontend/guide/engineering/tooling/monorepo">Monorepo、任务编排与构建缓存</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>“项目多就用 Monorepo”和“团队多就拆仓库”都过于简单。关键问题是代码是否经常一起变化、是否需要原子发布、权限是否必须隔离，以及组织能否维护统一工具链。</p><p>仓库不是部署边界。一个 Monorepo 可以产出多个独立服务，一个仓库也可以包含单体应用；不要用仓库数量替代架构讨论。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>受监管代码、客户定制源码或密钥配置需要满足访问隔离；</li><li>CI、代码托管和制品系统必须能处理预期仓库规模；</li><li>许可证和发布流程不能因共享源码而越界；</li><li>制品仍需有明确版本、负责人和供应链记录。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较跨项目原子变更、独立版本、权限、代码发现、工具统一、CI 性能、克隆成本、依赖升级、故障影响和平台团队能力。不能只比较本地安装速度。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-多仓库" tabindex="-1">3.1 多仓库 <a class="header-anchor" href="#_3-1-多仓库" aria-label="Permalink to &quot;3.1 多仓库&quot;">​</a></h3><p>每个应用或包独立版本和权限，适合生命周期、合规或技术栈明显不同的产品。共享能力需要发布制品并协调升级，跨仓变更通常经过兼容期。</p><h3 id="_3-2-单一-monorepo" tabindex="-1">3.2 单一 Monorepo <a class="header-anchor" href="#_3-2-单一-monorepo" aria-label="Permalink to &quot;3.2 单一 Monorepo&quot;">​</a></h3><p>多个应用和包共享仓库，可原子修改、统一检查和复用源码。适合频繁共同演进的产品族；需要受影响任务分析、构建缓存、所有者和边界规则，否则 CI 与耦合会扩大。</p><h3 id="_3-3-分域-monorepo" tabindex="-1">3.3 分域 Monorepo <a class="header-anchor" href="#_3-3-分域-monorepo" aria-label="Permalink to &quot;3.3 分域 Monorepo&quot;">​</a></h3><p>按产品线或信任边界建立少量 Monorepo，在域内共享，在域间发布制品。它接受部分跨仓协调，以换取规模和权限可控，适合大型组织的折中。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>多仓库</th><th>单一 Monorepo</th><th>分域 Monorepo</th></tr></thead><tbody><tr><td>跨项目原子修改</td><td>困难</td><td>容易</td><td>域内容易</td></tr><tr><td>权限隔离</td><td>强</td><td>需路径级治理</td><td>强</td></tr><tr><td>独立版本</td><td>自然</td><td>需工具支持</td><td>域间自然</td></tr><tr><td>统一工具链</td><td>易漂移</td><td>最容易</td><td>域内统一</td></tr><tr><td>CI 扩展</td><td>分散</td><td>需受影响分析和缓存</td><td>中等</td></tr><tr><td>代码发现</td><td>分散</td><td>集中</td><td>按领域集中</td></tr><tr><td>大规模事故影响</td><td>较局部</td><td>需严格门禁</td><td>中等</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：同一产品线有管理端、客户门户、组件库、API 客户端和三个构建插件，由 18 名工程师维护。过去半年 42% 的组件或契约变更需要同时修改两个以上仓库，发布等待中位数为三天；所有代码权限相同。</p><p>推荐迁入一个 Monorepo，并保留应用独立部署和包独立版本。采用工作区依赖、受影响任务、远程构建缓存和路径所有者；不允许应用通过相对路径读取其他应用源码，只能依赖公开包。</p><p>另一个受监管客户定制仓库继续独立，因为访问权限是硬约束，不应为了统一而放入同一仓库。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>收益是契约和消费者可原子修改、依赖升级集中、开发环境一致。代价是仓库级故障影响更广、CI 平台复杂、主干纪律要求提高，并可能出现“既然都在一起就随便导入”的耦合。</p><p>迁移应先统一包名、构建和测试契约，再搬历史；没有必要保留每个仓库的完整 Git 历史时，可用归档链接降低迁移复杂度。制品发布、变更记录和兼容策略仍然存在，不能用源码引用全部绕过。</p><p>退出成本来自共享配置和跨包源码耦合。保持独立 package 边界和可单独构建，可以为未来按领域拆仓保留路径。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>代码几乎不共同变化、团队和发布周期完全独立时，Monorepo 收益有限。</li><li>访问权限必须强隔离时，不应只依赖路径所有者。</li><li>没有受影响任务和缓存能力时，大仓库会拖慢所有反馈。</li><li>不要把 Monorepo 当成共享任意内部代码的许可。</li><li>为一个小应用和一个稳定工具包建设复杂任务平台通常不划算。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>同一产品线的五类代码是否合并仓库</td></tr><tr><td>硬约束</td><td>普通产品权限一致；受监管定制代码必须隔离；应用独立部署</td></tr><tr><td>候选</td><td>多仓库、单一 Monorepo、分域 Monorepo</td></tr><tr><td>决定</td><td>产品线 Monorepo；受监管仓库保持独立</td></tr><tr><td>证据</td><td>42% 变更跨仓；发布等待中位数 3 天；CI 支持远程缓存</td></tr><tr><td>边界措施</td><td>独立 package、公开 exports、路径所有者、受影响任务</td></tr><tr><td>接受代价</td><td>平台维护和主干故障影响扩大</td></tr><tr><td>成功指标</td><td>跨仓等待、CI P75、缓存命中、越界依赖、独立发布成功率</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当仓库规模使 CI P75 连续三个月超过预算、权限模型无法满足新监管边界、产品线几乎不再共同变化，或平台维护投入超过节省的跨仓成本时复查。若跨包越界依赖增长，应先加强边界，而不是立即拆仓。</p>',35)])])}const u=o(d,[["render",n]]);export{_ as __pageData,u as default};
